# Page replacement: FIFO, LRU, OPT, Clock on the classic string
refs = [7,0,1,2,0,3,0,4,2,3,0,3,2,1,2,0,1,7,0,1]

def fifo(refs, n):
    mem, faults = [], 0
    for r in refs:
        if r not in mem:
            faults += 1
            if len(mem) == n: mem.pop(0)    # evict oldest loaded
            mem.append(r)
    return faults

def lru(refs, n):
    mem, faults = [], 0                     # most recent at the end
    for r in refs:
        if r in mem: mem.remove(r)
        else:
            faults += 1
            if len(mem) == n: mem.pop(0)    # evict least recently used
        mem.append(r)
    return faults

def opt(refs, n):
    mem, faults = [], 0
    for i, r in enumerate(refs):
        if r in mem: continue
        faults += 1
        if len(mem) == n:
            def nxt(p):                     # next use, or infinity
                return refs[i+1:].index(p) if p in refs[i+1:] else 10**9
            mem.remove(max(mem, key=nxt))   # farthest next use
        mem.append(r)
    return faults

def clock(refs, n):
    frames, ref, hand, faults = [None]*n, [0]*n, 0, 0
    for r in refs:
        if r in frames:
            ref[frames.index(r)] = 1        # a hit only sets a bit
            continue
        faults += 1
        while ref[hand]:                    # second chance: clear and skip
            ref[hand] = 0
            hand = (hand + 1) % n
        frames[hand], ref[hand] = r, 1
        hand = (hand + 1) % n
    return faults

print("refs:", refs)
for name, f in (("FIFO", fifo), ("LRU", lru), ("OPT", opt), ("Clock", clock)):
    print(f"{name:5}: {f(refs, 3)} faults with 3 frames")

# Belady's anomaly: FIFO vs LRU on the same string
refs = [1,2,3,4,1,2,5,1,2,3,4,5]

def fifo(refs, n):
    mem, faults = [], 0
    for r in refs:
        if r not in mem:
            faults += 1
            if len(mem) == n: mem.pop(0)
            mem.append(r)
    return faults

def lru(refs, n):
    mem, faults = [], 0
    for r in refs:
        if r in mem: mem.remove(r)      # refresh recency
        else:
            faults += 1
            if len(mem) == n: mem.pop(0)
        mem.append(r)
    return faults

print("refs:", refs)
for n in (3, 4):
    print(f"{n} frames: FIFO {fifo(refs, n)} faults, LRU {lru(refs, n)} faults")
# FIFO gets worse with more frames (9 -> 10); LRU improves (10 -> 8).
